import arrtForm from "./components/relationManageComponent/arrtForm";
import { globalattrSearch, globalattrDel } from "@/api/system/relationManage";
export default {
  components: {
    arrtForm: arrtForm
  },
  data: function data() {
    return {
      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      // 弹窗
      showForm: false,
      showType: '',
      arrtId: ''
    };
  },
  mounted: function mounted() {
    this.setPageContentHeight();
    this.setTableHeight();
    this.getList();
  },
  methods: {
    // 设置表格高度
    setTableHeight: function setTableHeight() {
      var bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = bodyBox[0].offsetHeight + 'px';
    },
    getList: function getList() {
      var _this = this;
      this.tableLoading = true;
      globalattrSearch().then(function (res) {
        _this.tableData = res.Return;
        _this.tableLoading = false;
      }).catch(function () {
        _this.tableLoading = false;
      });
    },
    // 删除
    delArrt: function delArrt(row) {
      var _this2 = this;
      this.$confirm('确定删除该全局属性?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(function () {
        globalattrDel({
          id: row.id
        }).then(function (res) {
          _this2.$message({
            type: 'success',
            message: '删除成功！'
          });
          _this2.getList();
        });
      });
    },
    // 编辑
    editArrt: function editArrt(row) {
      this.showType = '修改';
      this.arrtId = row.id;
      this.showForm = true;
    },
    saveGlobalArrt: function saveGlobalArrt() {
      this.showForm = false;
      this.getList();
    }
  }
};
